using System;using System.IO;using System.Linq;using System.Collections.Generic;using UnityEngine;using UnityEditor;using UnityEditor.SceneManagement;using UnityEngine.SceneManagement;using UnityEngine.Rendering.Universal;using Newtonsoft.Json;using Newtonsoft.Json.Linq;
public static class F1Review {
 static string R=>Path.GetFullPath(Path.Combine(Application.dataPath,"../../.."));static string H=>R+"/SourceAssets/F1_FullFloor/";static string O=>R+"/Docs/Review/2026-11-12_1F_FullFloor/";
 static Vector3 V(JToken a)=>new Vector3((float)a[0],(float)a[1],(float)a[2]);static float[] A(Vector3 a)=>new[]{a.x,a.y,a.z};
 static Scene Check(){var s=SceneManager.GetActiveScene();if(s.isDirty||Application.isPlaying||!s.path.EndsWith("Level_1F_Factory.unity"))throw new Exception("Saved 1F edit required");return s;}
 static void Shot(string file,Vector3 pos,Vector3 target,float fov=78){var go=new GameObject("F1_ReviewCamera"){hideFlags=HideFlags.HideAndDontSave};var c=go.AddComponent<Camera>();c.transform.position=pos;c.transform.LookAt(target);c.useOcclusionCulling=false;c.nearClipPlane=.03f;c.farClipPlane=300;c.fieldOfView=fov;c.GetUniversalAdditionalCameraData().renderPostProcessing=false;var rt=new RenderTexture(1600,1000,24){antiAliasing=4};var old=RenderTexture.active;Texture2D tex=null;try{c.targetTexture=rt;c.Render();RenderTexture.active=rt;tex=new Texture2D(1600,1000,TextureFormat.RGB24,false);tex.ReadPixels(new Rect(0,0,1600,1000),0,0);tex.Apply();File.WriteAllBytes(O+file+".jpg",tex.EncodeToJPG(92));}finally{RenderTexture.active=old;c.targetTexture=null;if(tex)UnityEngine.Object.DestroyImmediate(tex);UnityEngine.Object.DestroyImmediate(rt);UnityEngine.Object.DestroyImmediate(go);}}
 public static object Capture(){var s=Check();var p=JObject.Parse(File.ReadAllText(H+"resolved.json"));var player=s.GetRootGameObjects().Single(g=>g.name.StartsWith("Player"));player.SetActive(false);var views=new List<object>();void Photo(string n,Vector3 a,Vector3 b,float fov=78){Shot(n,a,b,fov);views.Add(new{name=n,position=A(a),target=A(b),fov});}
  try{Photo("C01_production",new Vector3(-23,1.7f,-10),new Vector3(-8,1.6f,5),86);Photo("C01_press",new Vector3(-12,1.7f,7),new Vector3(-16,1.7f,2),76);Photo("C02_loading",new Vector3(30,1.7f,-15),new Vector3(20,1.4f,-1),86);Photo("C04_office",new Vector3(-6.5f,1.7f,20),new Vector3(-15,1.2f,29),86);Photo("C04_desks",new Vector3(-15.5f,1.65f,26.7f),new Vector3(-14.5f,.96f,28.8f),74);Photo("C03_checkpoint",new Vector3(-35,1.7f,-30.5f),new Vector3(-27,1.3f,-23),88);Photo("OUT_gate",new Vector3(-49,1.7f,-29),new Vector3(-63,1.3f,-28),75);
   foreach(var a in p["arrivals"]){var v=V(a["position"]);Photo((string)a["id"]+"_arrival",v+Vector3.up*1.7f,v+new Vector3(0,1.4f,8),84);}
   foreach(var t in p["tunnels"]){var pts=t["path"].Select(v=>new Vector3((float)v[0],1.7f,(float)v[1])).ToArray();var a=pts[0];var b=pts[1];Photo((string)t["id"]+"_link",Vector3.Lerp(a,b,.5f),b,78);}
   Photo("Exterior_factory",new Vector3(-75,17,-64),new Vector3(-9,1,0),62);
   foreach(var g in s.GetRootGameObjects().SelectMany(g=>g.GetComponentsInChildren<Transform>()).Where(t=>t.name.EndsWith("_Roof")))g.gameObject.SetActive(false);
   Photo("overview",new Vector3(-70,84,-84),new Vector3(-2,0,0),65);foreach(var r in p["rooms"]){float x=(float)r["x"],z=(float)r["z"],w=(float)r["w"],d=(float)r["d"];Photo((string)r["id"]+"_overview",new Vector3(x-w*.6f,Mathf.Max(w,d)*.9f,z-d*.8f),new Vector3(x,.6f,z),65);}
  }finally{EditorSceneManager.OpenScene(s.path);}File.WriteAllText(O+"views.json",JsonConvert.SerializeObject(views,Formatting.Indented));return new{images=views.Count};
 }
 public static object Audit(){var s=Check();var root=GameObject.Find("1F_AbandonedFactory");var errors=new List<string>();var p=JObject.Parse(File.ReadAllText(H+"resolved.json"));var sample=new List<object>();
  foreach(var q in p["placements"]){var g=GameObject.Find((string)q["name"]);if(!g){errors.Add("Missing "+q["name"]);continue;}if(Vector3.Distance(g.transform.position,V(q["position"]))>.002f)errors.Add("Position "+g.name);if(Quaternion.Angle(g.transform.rotation,Quaternion.Euler(0,(float)q["yaw"],0))>.01f)errors.Add("Rotation "+g.name);var rs=g.GetComponentsInChildren<Renderer>();var b=rs.First().bounds;foreach(var r in rs)b.Encapsulate(r.bounds);sample.Add(new{g.name,model=(string)q["model"],min=A(b.min),max=A(b.max)});}
  foreach(var f in root.GetComponentsInChildren<MeshFilter>(true))if(!f.sharedMesh)errors.Add("Missing mesh "+f.name);foreach(var r in root.GetComponentsInChildren<Renderer>(true))if(r.sharedMaterials.Any(m=>!m||!m.shader))errors.Add("Missing material "+r.name);
  var floorRays=p["rooms"].Select(r=>{var pos=new Vector3((float)r["x"],.3f,(float)r["z"]);bool hit=Physics.Raycast(pos,Vector3.down,out var h,.6f);return new{id=(string)r["id"],hit,normal=hit?A(h.normal):null,collider=hit?h.collider.name:null};}).ToArray();
  var result=new{scene=s.path,saved=!s.isDirty,errors,placements=p["placements"].Count(),missingScripts=root.GetComponentsInChildren<Transform>(true).Sum(t=>GameObjectUtility.GetMonoBehavioursWithMissingScriptCount(t.gameObject)),lights=root.GetComponentsInChildren<Light>().Count(),shadowLights=root.GetComponentsInChildren<Light>().Count(l=>l.shadows!=LightShadows.None),lodGroups=root.GetComponentsInChildren<LODGroup>().Length,newReadableMeshes=root.GetComponentsInChildren<MeshFilter>().Count(f=>f.sharedMesh&&AssetDatabase.GetAssetPath(f.sharedMesh).Contains("/F1_")&&f.sharedMesh.isReadable),floorRays};File.WriteAllText(O+"audit.json",JsonConvert.SerializeObject(result,Formatting.Indented));File.WriteAllText(O+"bounds.json",JsonConvert.SerializeObject(sample,Formatting.Indented));return result;
 }
}
